<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { BadgeCheck, CarFront, Check, ChevronRight, CircleUserRound, Cpu, Edit3, KeyRound, Mail, MoreHorizontal, Plus, RefreshCw, Search, ShieldCheck, Smartphone, UserPlus, UsersRound } from 'lucide-vue-next'
import PageHeader from '../components/common/PageHeader.vue'
import StatePanel from '../components/common/StatePanel.vue'
import StatusBadge from '../components/common/StatusBadge.vue'
import AppModal from '../components/common/AppModal.vue'
import { api } from '../api'
import { asApiError, type ApiError } from '../api/errors'
import type { DeviceInfo, Role, User, Vehicle } from '../types/api'
import { useFleetStore } from '../stores/fleet'
import { useUiStore } from '../stores/ui'
import { formatTime, relativeTime } from '../utils/format'
const fleet=useFleetStore(),ui=useUiStore(),router=useRouter()
const tab=ref<'users'|'vehicles'|'devices'>('users'),users=ref<User[]>([]),devices=ref<DeviceInfo[]>([]),loading=ref(true),error=ref<ApiError|null>(null),search=ref('')
const userOpen=ref(false),deviceOpen=ref(false),vehicleOpen=ref(false),saving=ref(false),editingVehicle=ref<Vehicle>(),vehicleName=ref('')
const userForm=reactive({username:'',display_name:'',email:'',password:'',roles:['user'] as Role[]})
const deviceForm=reactive({vin:'',serial_number:''})
const filteredUsers=computed(()=>users.value.filter(u=>`${u.display_name}${u.username}${u.email}`.toLowerCase().includes(search.value.toLowerCase())))
const filteredVehicles=computed(()=>fleet.vehicles.filter(v=>`${v.display_name}${v.vin}${v.model}`.toLowerCase().includes(search.value.toLowerCase())))
const filteredDevices=computed(()=>devices.value.filter(d=>`${d.vin}${d.serial_number}${d.hardware}`.toLowerCase().includes(search.value.toLowerCase())))
const adminCount=computed(()=>users.value.filter(u=>u.roles.includes('admin')).length)
async function load(){loading.value=true;error.value=null;try{[users.value,devices.value]=await Promise.all([api.listUsers(),api.listDevices()])}catch(cause){error.value=asApiError(cause)}finally{loading.value=false}}
function editVehicle(vehicle:Vehicle){editingVehicle.value=vehicle;vehicleName.value=vehicle.display_name;vehicleOpen.value=true}
async function createUser(){saving.value=true;try{const user=await api.createUser(userForm);users.value.push(user);userOpen.value=false;Object.assign(userForm,{username:'',display_name:'',email:'',password:'',roles:['user']});ui.toast('用户邀请已创建','success','账号将由服务端发送激活通知')}catch(cause){ui.toast('创建用户失败','error',asApiError(cause).message)}finally{saving.value=false}}
async function toggleUser(user:User){try{const updated=await api.updateUserStatus(user.id,user.status==='suspended'?'active':'suspended');Object.assign(user,updated);ui.toast(updated.status==='suspended'?'用户已停用':'用户已启用','success')}catch(cause){ui.toast('状态更新失败','error',asApiError(cause).message)}}
async function provision(){saving.value=true;try{const device=await api.provisionDevice(deviceForm);devices.value.unshift(device);deviceOpen.value=false;Object.assign(deviceForm,{vin:'',serial_number:''});ui.toast('设备已进入预配置流程','success','上线状态以设备真实连接为准')}catch(cause){ui.toast('设备预配置失败','error',asApiError(cause).message)}finally{saving.value=false}}
async function saveVehicle(){if(!editingVehicle.value)return;saving.value=true;try{const updated=await api.updateVehicle(editingVehicle.value.vin,vehicleName.value);const index=fleet.vehicles.findIndex(v=>v.vin===updated.vin);if(index>=0)fleet.vehicles[index]=updated;vehicleOpen.value=false;ui.toast('车辆资料已更新','success')}catch(cause){ui.toast('车辆更新失败','error',asApiError(cause).message)}finally{saving.value=false}}
onMounted(()=>void load())
</script>
<template>
  <div class="page access-page">
    <PageHeader eyebrow="IDENTITY & ASSETS" title="用户与资产" subtitle="统一管理企业成员、授权车辆与车端设备，权限边界由服务端强制执行。"><template #actions><button class="btn btn-secondary" @click="load"><RefreshCw/>同步目录</button><button class="btn btn-primary" @click="tab==='devices'?deviceOpen=true:tab==='users'?userOpen=true:router.push('/fleet')"><Plus/>{{ tab==='devices'?'预配置设备':tab==='users'?'邀请用户':'查看车辆' }}</button></template></PageHeader>
    <div class="access-metrics"><article class="card"><UsersRound/><div><strong>{{ users.length }}</strong><span>企业成员</span></div><small>跨角色协作</small></article><article class="card"><ShieldCheck/><div><strong>{{ adminCount }}</strong><span>运营管理员</span></div><small>最小权限授权</small></article><article class="card"><CarFront/><div><strong>{{ fleet.vehicles.length }}</strong><span>授权车辆</span></div><small>多用户车辆关系</small></article><article class="card"><Cpu/><div><strong>{{ devices.length }}</strong><span>车端设备</span></div><small>mTLS 证书保护</small></article></div>
    <StatePanel :loading="loading" :error="error" @retry="load">
      <section class="card access-card"><div class="access-toolbar"><div class="access-tabs"><button :class="{active:tab==='users'}" @click="tab='users'"><CircleUserRound/>用户</button><button :class="{active:tab==='vehicles'}" @click="tab='vehicles'"><CarFront/>车辆</button><button :class="{active:tab==='devices'}" @click="tab='devices'"><Cpu/>设备</button></div><div class="search-field"><Search/><input v-model="search" class="input" placeholder="搜索当前目录"></div></div>
        <div v-if="tab==='users'" class="table-wrap"><table><thead><tr><th>成员</th><th>角色</th><th>状态</th><th>最近活跃</th><th>创建日期</th><th/></tr></thead><tbody><tr v-for="user in filteredUsers" :key="user.id"><td><div class="member-cell"><span class="avatar">{{ user.display_name.slice(0,1) }}</span><div><strong>{{ user.display_name }}</strong><small>{{ user.email }} · @{{ user.username }}</small></div></div></td><td><span class="role-badge" :class="{admin:user.roles.includes('admin')}"><ShieldCheck/>{{ user.roles.includes('admin')?'运营管理员':'车队成员' }}</span></td><td><StatusBadge :status="user.status||'active'" :label="user.status==='invited'?'待激活':user.status==='suspended'?'已停用':'正常'"/></td><td>{{ user.last_active_at?relativeTime(new Date(user.last_active_at).getTime()):'尚未登录' }}</td><td>{{ formatTime(user.created_at,true) }}</td><td><button class="btn btn-ghost btn-sm" @click="toggleUser(user)">{{ user.status==='suspended'?'启用':'停用' }}<MoreHorizontal/></button></td></tr></tbody></table><StatePanel :empty="!filteredUsers.length" compact/></div>
        <div v-else-if="tab==='vehicles'" class="table-wrap"><table><thead><tr><th>车辆</th><th>VIN</th><th>当前权限</th><th>固件版本</th><th>连接状态</th><th>创建日期</th><th/></tr></thead><tbody><tr v-for="vehicle in filteredVehicles" :key="vehicle.vin"><td><div class="member-cell"><span class="asset-icon"><CarFront/></span><div><strong>{{ vehicle.display_name }}</strong><small>{{ vehicle.model_year }} {{ vehicle.model }}</small></div></div></td><td class="mono">{{ vehicle.vin }}</td><td><span class="role-badge"><KeyRound/>{{ vehicle.access_role }}</span></td><td>OS {{ vehicle.firmware_version }}</td><td><StatusBadge :status="fleet.isOnline(vehicle.vin)?'online':'offline'"/></td><td>{{ formatTime(vehicle.created_at,true) }}</td><td><div class="row"><button class="btn btn-ghost btn-icon btn-sm" title="编辑名称" @click="editVehicle(vehicle)"><Edit3/></button><button class="btn btn-ghost btn-icon btn-sm" @click="router.push(`/vehicles/${vehicle.vin}`)"><ChevronRight/></button></div></td></tr></tbody></table><StatePanel :empty="!filteredVehicles.length" compact/></div>
        <div v-else class="table-wrap"><table><thead><tr><th>设备</th><th>绑定 VIN</th><th>硬件版本</th><th>固件</th><th>证书有效期</th><th>连接状态</th><th>最后在线</th></tr></thead><tbody><tr v-for="device in filteredDevices" :key="device.id"><td><div class="member-cell"><span class="asset-icon device"><Smartphone/></span><div><strong class="mono">{{ device.serial_number }}</strong><small>{{ device.id }}</small></div></div></td><td class="mono">{{ device.vin }}</td><td>{{ device.hardware }}</td><td>{{ device.firmware_version }}</td><td><span class="certificate"><BadgeCheck/>{{ formatTime(device.certificate_expires_at,true) }}</span></td><td><StatusBadge :status="device.status"/></td><td>{{ relativeTime(device.last_seen_at_ms) }}</td></tr></tbody></table><StatePanel :empty="!filteredDevices.length" compact/></div>
        <div class="access-footer"><ShieldCheck/>服务端会再次校验用户角色、车辆关系与设备身份；隐藏按钮不是权限控制。<span>共 {{ tab==='users'?filteredUsers.length:tab==='vehicles'?filteredVehicles.length:filteredDevices.length }} 条记录</span></div>
      </section>
    </StatePanel>
    <AppModal :open="userOpen" title="邀请企业成员" eyebrow="NEW IDENTITY" :busy="saving" @close="userOpen=false"><div class="form-grid"><div class="field"><label>显示姓名</label><input v-model="userForm.display_name" class="input" placeholder="例如：江澄"></div><div class="field"><label>登录账号</label><input v-model="userForm.username" class="input" placeholder="name.department"></div><div class="field full"><label>企业邮箱</label><input v-model="userForm.email" type="email" class="input" placeholder="name@aurora.auto"></div><div class="field full"><label>临时密码</label><input v-model="userForm.password" type="password" class="input" placeholder="至少 8 位，仅用于本次创建"></div><div class="field full"><label>角色</label><select v-model="userForm.roles[0]" class="select"><option value="user">车队成员</option><option value="admin">运营管理员</option></select></div></div><p class="form-note"><Mail/>真实环境中由服务端校验角色并发送邀请；演示模式仅修改本地演示目录。</p><template #footer><button class="btn btn-secondary" @click="userOpen=false">取消</button><button class="btn btn-primary" :disabled="saving||!userForm.username||!userForm.display_name||userForm.password.length<8" @click="createUser"><UserPlus/>创建邀请</button></template></AppModal>
    <AppModal :open="deviceOpen" title="预配置车端设备" eyebrow="DEVICE PROVISIONING" :busy="saving" @close="deviceOpen=false"><div class="form-grid"><div class="field full"><label>绑定车辆 VIN</label><select v-model="deviceForm.vin" class="select"><option value="">选择授权车辆</option><option v-for="vehicle in fleet.vehicles" :key="vehicle.vin" :value="vehicle.vin">{{ vehicle.display_name }} · {{ vehicle.vin }}</option></select></div><div class="field full"><label>设备序列号</label><input v-model="deviceForm.serial_number" class="input mono" placeholder="AUR-TCU-0000"></div></div><p class="form-note"><KeyRound/>设备上线仍需有效 mTLS 证书，证书 CN 必须与 VIN 一致。预配置不代表车辆已在线。</p><template #footer><button class="btn btn-secondary" @click="deviceOpen=false">取消</button><button class="btn btn-primary" :disabled="saving||!deviceForm.vin||!deviceForm.serial_number" @click="provision"><Plus/>开始预配置</button></template></AppModal>
    <AppModal :open="vehicleOpen" title="编辑车辆资料" eyebrow="VEHICLE PROFILE" :busy="saving" @close="vehicleOpen=false"><div class="field"><label>车辆显示名称</label><input v-model="vehicleName" class="input" maxlength="40"></div><p class="form-note"><Check/>VIN、车主关系与硬件标识不可由前端直接修改。</p><template #footer><button class="btn btn-secondary" @click="vehicleOpen=false">取消</button><button class="btn btn-primary" :disabled="saving||!vehicleName" @click="saveVehicle">保存更改</button></template></AppModal>
  </div>
</template>
<style scoped>
.access-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:18px}.access-metrics article{display:flex;align-items:center;gap:13px;padding:18px 20px}.access-metrics article>svg{width:19px;color:var(--primary)}.access-metrics article>div{display:flex;flex-direction:column}.access-metrics strong{font-size:22px;line-height:1}.access-metrics span{font-size:9px;color:var(--text-2);margin-top:5px}.access-metrics small{margin-left:auto;font-size:8px;color:var(--muted)}.access-toolbar{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--line)}.access-tabs{display:flex;gap:6px}.access-tabs button{border:0;background:transparent;color:var(--muted);padding:8px 13px;display:flex;align-items:center;gap:6px;font-size:10px;border-radius:8px;cursor:pointer}.access-tabs button.active{background:var(--primary-soft);color:var(--primary);font-weight:650}.access-tabs svg{width:14px}.member-cell{display:flex;align-items:center;gap:10px}.member-cell>div{display:flex;flex-direction:column;gap:4px}.member-cell small{font-size:8px;color:var(--muted)}.role-badge{display:inline-flex;align-items:center;gap:5px;color:var(--text-2);font-size:9px;background:var(--surface-2);padding:5px 8px;border-radius:6px}.role-badge.admin{background:var(--primary-soft);color:var(--primary)}.role-badge svg{width:11px}.asset-icon{width:33px;height:33px;border-radius:9px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center}.asset-icon.device{background:var(--cyan-soft);color:var(--cyan)}.asset-icon svg{width:15px}.certificate{display:flex;align-items:center;gap:5px;color:var(--green);font-size:9px}.certificate svg{width:12px}.access-footer{display:flex;align-items:center;gap:7px;padding:12px 18px;background:var(--bg-soft);border-top:1px solid var(--line);font-size:8px;color:var(--muted)}.access-footer svg{width:12px;color:var(--green)}.access-footer span{margin-left:auto}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-grid .full{grid-column:1/-1}.form-note{display:flex;align-items:flex-start;gap:7px;font-size:9px;line-height:1.6;color:var(--muted);margin-top:16px}.form-note svg{width:13px;flex:none;margin-top:1px;color:var(--primary)}
@media(max-width:1100px){.access-metrics{grid-template-columns:1fr 1fr}.access-metrics small{display:none}}
</style>
